def solve(values, k):
    from collections import deque
    candidates, answer = deque(), []
    for i, value in enumerate(values):
        while candidates and candidates[0] <= i-k: candidates.popleft()
        while candidates and values[candidates[-1]] <= value: candidates.pop()
        candidates.append(i)
        if i >= k-1: answer.append(values[candidates[0]])
    return answer
